#include <stdio.h>

/* F(0)=0, F(1)=1, F(n)=F(n-1)+F(n-2), tinh bang de quy that su */
long long fib(int n) {
    if (n < 2) return n;           /* truong hop co so: F(0)=0, F(1)=1 */
    return fib(n - 1) + fib(n - 2); /* buoc de quy */
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    printf("%lld\n", fib(n));
    return 0;
}
